entries[171616] = { ["name"] = "Witherhide Cliffstomper", ["text"] = "1.5 sec cast\nSummons and dismisses your Witherhide Cliffstomper.\n\"Tiny notches cover the hooves of this variation of clefthoof, allowing it to safely scale mountainous regions in search of food.\"\nVendor:\nTrader Araanda\nZone:\nLunarfall\nCost:\n20000\n\nVendor:\nTrader Darakk\nZone:\nFrostwall\nCost:\n20000" }
entries[171617] = { ["name"] = "Trained Icehoof", ["text"] = "1.5 sec cast\nSummons and dismisses your Trained Icehoof.\n\"It wasn't until you owned this mount that you understood how much the world of Draenor would test you. Clefthoof hair gets in everything!\"\nSource:\nGarrison Stables" }
entries[171618] = { ["name"] = "Ancient Leatherhide", ["text"] = "1.5 sec cast\nSummons and dismisses your Ancient Leatherhide." }
entries[171619] = { ["name"] = "Tundra Icehoof", ["text"] = "1.5 sec cast\nSummons and dismisses your Tundra Icehoof.\n\"A translucent layer of down hair covers this breed's leathery hide, acting as the perfect insulation for cold environments.\"\nDrop:\nVengeance, Deathtalon, Terrorfist, Doomroller\nZone:\nTanaan Jungle" }
entries[171620] = { ["name"] = "Bloodhoof Bull", ["text"] = "1.5 sec cast\nSummons and dismisses your Bloodhoof Bull.\n\"Members of the Warsong clan have long hunted these clefthoof to use their crimson-hued skin for battle standards.\"\nDrop:\nNakk the Thunderer\nLocation:\nNagrand" }
entries[171621] = { ["name"] = "Ironhoof Destroyer", ["text"] = "1.5 sec cast\nSummons and dismisses your Ironhoof Destroyer.\n\"Blackhand is said to have personally designed the fiery armaments used on the Iron Horde's clefthoof battle mounts.\"\nDrop:\nBlackhand\nLocation:\nBlackrock Foundry (Mythic)" }
entries[171622] = { ["name"] = "Mottled Meadowstomper", ["text"] = "1.5 sec cast\nSummons and dismisses your Mottled Meadowstomper.\n\"The elekk's long trunk allows it to sniff out sources of food, avoid danger, and steal snacks from your bags when you're not looking.\"\nDrop:\nLuk'hok\nZone:\nNagrand" }
entries[171623] = { ["name"] = "Trained Meadowstomper", ["text"] = "1.5 sec cast\nSummons and dismisses your Trained Meadowstomper.\n\"The draenei perfected elekk husbandry long ago, adorning the creatures with Light-infused crystals to make them more docile.\"\nQuest:\nGarrison Stables" }
entries[171624] = { ["name"] = "Shadowhide Pearltusk", ["text"] = "1.5 sec cast\nSummons and dismisses your Shadowhide Pearltusk.\n\"Some legends say the draenei first befriended the elekk after one of the beasts saved an injured scout from a pack of vicious podlings.\"\nDrop:\nInvader's Forgotten Treasure" }
entries[171625] = { ["name"] = "Dusty Rockhide", ["text"] = "1.5 sec cast\nSummons and dismisses your Dusty Rockhide.\n\"Ever since acquiring this mount, you have been plagued by strange fever dreams of hippety-hoppety clippety-cloppety elekk on parade.\"\nVendor:\nVindicator Nuurem\nCouncil of Exarchs - Exalted\nLocation:\nStormshield\nCost:\n5,000\n+ 5,000" }
entries[171626] = { ["name"] = "Armored Irontusk", ["text"] = "1.5 sec cast\nSummons and dismisses your Armored Irontusk.\n\"It is said an elekk never forgets. No wonder it despises the Iron Horde, considering the torment the orcs put the beast through.\"\nVendor:\n\nSha'tari Defense - Exalted\nLocation:\nGarrison Trading Post\nCost:\n5,000\n+ 5,000" }
entries[171627] = { ["name"] = "Blacksteel Battleboar", ["text"] = "1.5 sec cast\nSummons and dismisses your Blacksteel Battleboar.\n\"Refuses to run unless its head is covered in heavy, spiked metal. It's an ego thing.\"\nAchievement:\nGuild Glory of the Draenor Raider" }
entries[171628] = { ["name"] = "Rocktusk Battleboar", ["text"] = "1.5 sec cast\nSummons and dismisses your Rocktusk Battleboar.\n\"It's not the metal helmet that attracts mates; it's the sweet mohawk.\"\nVendor:\nTrader Araanda\nZone:\nLunarfall\nCost:\n10000\n\nVendor:\nTrader Darakk\nZone:\nFrostwall\nCost:\n10000" }
entries[171629] = { ["name"] = "Armored Frostboar", ["text"] = "1.5 sec cast\nSummons and dismisses your Armored Frostboar.\n\"Subsists almost entirely on a diet of frozen berries. Though it finds slow off-worlders equally tasty.\"\nAchievement:\nAdvanced Husbandry" }
entries[171630] = { ["name"] = "Armored Razorback", ["text"] = "1.5 sec cast\nSummons and dismisses your Armored Razorback.\n\"Never... ever... EVER... let it smell bacon on you.\"\nDrop:\nVengeance, Deathtalon, Terrorfist, Doomroller\nZone:\nTanaan Jungle" }
entries[171631] = { ["name"] = "Achievement Credit", ["text"] = "Instant\nEnables the display of guild banners at your Garrison." }
entries[171632] = { ["name"] = "Frostplains Battleboar", ["text"] = "1.5 sec cast\nSummons and dismisses your Frostplains Battleboar.\n\"If it didn't have the cool tusk ring, it would feel so silly in that outfit.\"\nAchievement:\nGlory of the Draenor Hero" }
entries[171633] = { ["name"] = "Wild Goretusk", ["text"] = "1.5 sec cast\nSummons and dismisses your Wild Goretusk.\n\"If you want a gentle ride, go find a \"tame happytusk\" or something.\"\nVendor:\nZ'tenga the Walker\nZone:\nTanaan Jungle\nThe Saberstalkers - Honored\nCost:\n1000" }
entries[171634] = { ["name"] = "Domesticated Razorback", ["text"] = "1.5 sec cast\nSummons and dismisses your Domesticated Razorback.\n\"Domesticated\" does not mean \"friendly.\" Bring some treats.\nVendor:\nGazrix Gearlock / Mimi Wizzlebub\nSteamwheedle \"Preservation\" Society - Exalted\nLocation:\nStormshield / Warspear\nCost:\n5,000\n+ 5,000" }
entries[171635] = { ["name"] = "Giant Coldsnout", ["text"] = "1.5 sec cast\nSummons and dismisses your Giant Coldsnout.\n\"Its snout is not just cold but wet. Not a pleasant way to wake up.\"\nDrop:\nInvader's Forgotten Treasure" }
entries[171636] = { ["name"] = "Great Greytusk", ["text"] = "1.5 sec cast\nSummons and dismisses your Great Greytusk.\n\"Sheds its tusks once a year. Is extremely shy until they grow back.\"\nDrop:\nGorok\nZone:\nFrostfire Ridge" }
entries[171637] = { ["name"] = "Trained Rocktusk", ["text"] = "1.5 sec cast\nSummons and dismisses your Trained Rocktusk.\n\"Thoroughly trained in how to snort, trot, and stomp on the faces of its enemies.\"\nQuest:\nGarrison Stables" }
